INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2833729, 394149, 35545, '<td valign="top">Needs to be larger and in better focus.</td>', 'Needs to be larger and in better focus.', '2006-09-14 00:55:21.000000', NULL, 1),
(2833786, 394891, 53668, '<td valign="top">''Origins of Woody...''</td>', '''Origins of Woody...''', '2006-09-14 01:11:16.000000', NULL, 1),
(2833920, 395295, 40430, '<td valign="top">defintely a great macro shot, WOW!</td>', 'defintely a great macro shot, WOW!', '2006-09-14 01:58:46.000000', NULL, 1),
(2833921, 395202, 40430, '<td valign="top">seems a bit dark  but might be my monitor.</td>', 'seems a bit dark  but might be my monitor.', '2006-09-14 01:59:44.000000', NULL, 1),
(2834001, 394777, 65025, '<td valign="top">It''s a great "found" shape.  The one thing I want is some different background.  Either a plane background, or something geometric without all the messy cars.</td>', 'It''s a great "found" shape.  The one thing I want is some different background.  Either a plane background, or something geometric without all the messy cars.', '2006-09-14 03:10:19.000000', NULL, 1),
(2834002, 392412, 24674, '<td valign="top">What you mean is concentric, not congruent.<br/>I wish you had just photographed the lower part and called it radial lines.</td>', 'What you mean is concentric, not congruent.I wish you had just photographed the lower part and called it radial lines.', '2006-09-14 03:10:38.000000', NULL, 1),
(2834004, 394235, 65025, '<td valign="top">I like how you made geometry messy, in a clean way.  Does that make sense?  Probably not.  But I think it fits the assignment and looks good!</td>', 'I like how you made geometry messy, in a clean way.  Does that make sense?  Probably not.  But I think it fits the assignment and looks good!', '2006-09-14 03:11:32.000000', NULL, 1),
(2834006, 395396, 65025, '<td valign="top">Ah...toys!</td>', 'Ah...toys!', '2006-09-14 03:12:01.000000', NULL, 1),
(2834009, 395411, 65025, '<td valign="top">Beautiful photo, I just don''t think of it as geometry!  I just want harder lines!</td>', 'Beautiful photo, I just don''t think of it as geometry!  I just want harder lines!', '2006-09-14 03:13:25.000000', NULL, 1),
(2834010, 394224, 24674, '<td valign="top">I really like this image.</td>', 'I really like this image.', '2006-09-14 03:13:46.000000', NULL, 1),
(2834012, 395370, 65025, '<td valign="top">Nice and simple....I wish I could do that.</td>', 'Nice and simple....I wish I could do that.', '2006-09-14 03:14:03.000000', NULL, 1),
(2834015, 394777, 24674, '<td valign="top">Good concept but there''s just too much distraction in the background.</td>', 'Good concept but there''s just too much distraction in the background.', '2006-09-14 03:15:43.000000', NULL, 1),
(2834016, 394055, 65025, '<td valign="top">This is a great photo.  And I think one thing that REALLY makes it is the two highlights on the sides of the track.  That, and that the entire thing isn''t a silhouette.  It has the red highlights as well.  Good job.</td>', 'This is a great photo.  And I think one thing that REALLY makes it is the two highlights on the sides of the track.  That, and that the entire thing isn''t a silhouette.  It has the red highlights as well.  Good job.', '2006-09-14 03:15:52.000000', NULL, 1),
(2834018, 394698, 65025, '<td valign="top">It''s simple AND hurts my eyes at the same time!  I like it.</td>', 'It''s simple AND hurts my eyes at the same time!  I like it.', '2006-09-14 03:17:03.000000', NULL, 1),
(2834019, 394698, 24674, '<td valign="top">Perfect.</td>', 'Perfect.', '2006-09-14 03:17:11.000000', NULL, 1),
(2834022, 392633, 24674, '<td valign="top">I know it meets the challenge description, but this is really ugly.<br/>Sorry.</td>', 'I know it meets the challenge description, but this is really ugly.Sorry.', '2006-09-14 03:18:03.000000', NULL, 1),
(2834024, 395349, 65025, '<td valign="top">Great photo.  The only thing I would change, and I am being WAY to nitpicky (it''s just that the photo is already really strong)  Is to stand on something....a car, a stool, whatever, to get the sun a little farther away from the trees...Sorry, graphic design class speeking.</td>', 'Great photo.  The only thing I would change, and I am being WAY to nitpicky (it''s just that the photo is already really strong)  Is to stand on something....a car, a stool, whatever, to get the sun a little farther away from the trees...Sorry, graphic design class speeking.', '2006-09-14 03:19:40.000000', NULL, 1),
(2834025, 392304, 24674, '<td valign="top">The branches are too distracting.<br/>Should have gone closer to get the subject clearly in the foreground.</td>', 'The branches are too distracting.Should have gone closer to get the subject clearly in the foreground.', '2006-09-14 03:20:36.000000', NULL, 1),
(2834028, 395044, 65025, '<td valign="top">Decaying geometery, aye?  I like it</td>', 'Decaying geometery, aye?  I like it', '2006-09-14 03:22:40.000000', NULL, 1),
(2834030, 395030, 24674, '<td valign="top">What is it ?</td>', 'What is it ?', '2006-09-14 03:23:31.000000', NULL, 1),
(2834031, 395295, 65025, '<td valign="top">Wow, didn''t realize how geometric flies eyes are!</td>', 'Wow, didn''t realize how geometric flies eyes are!', '2006-09-14 03:23:58.000000', NULL, 1),
(2834033, 393191, 65025, '<td valign="top">Your point of view makes both of my eyes want to move outward at the same time.  I love it.</td>', 'Your point of view makes both of my eyes want to move outward at the same time.  I love it.', '2006-09-14 03:25:29.000000', NULL, 1),
(2834034, 394933, 24674, '<td valign="top">Not sure if it is intentional, but the head of the compass has become the focal point in this picture, and it looks distractingly like a face.</td>', 'Not sure if it is intentional, but the head of the compass has become the focal point in this picture, and it looks distractingly like a face.', '2006-09-14 03:25:30.000000', NULL, 1),
(2834036, 395323, 65025, '<td valign="top">I think it''s a good concept. One thing that might be cool is bringing out the a bit so the shadows are more visible.  Also, people might tell you to color correct the image...but I like it.  Just my style I guess.  I think the yellow emphasizes the "home" feel and makes it more interesting.</td>', 'I think it''s a good concept. One thing that might be cool is bringing out the a bit so the shadows are more visible.  Also, people might tell you to color correct the image...but I like it.  Just my style I guess.  I think the yellow emphasizes the "home" feel and makes it more interesting.', '2006-09-14 03:28:08.000000', NULL, 1),
(2834040, 394950, 65025, '<td valign="top">I love how I can tell what the object is by only seeing about 1/4 of the object.</td>', 'I love how I can tell what the object is by only seeing about 1/4 of the object.', '2006-09-14 03:34:29.000000', NULL, 1),
(2834066, 394765, 55956, '<td valign="top">very good, i like it. great the black and white.</td>', 'very good, i like it. great the black and white.', '2006-09-14 04:10:55.000000', NULL, 1),
(2834067, 394055, 65552, '<td valign="top">Awesome photograph. I love the color!</td>', 'Awesome photograph. I love the color!', '2006-09-14 04:12:46.000000', NULL, 1),
(2834093, 393421, 64462, '<td valign="top">what is this building?</td>', 'what is this building?', '2006-09-14 04:48:17.000000', NULL, 1),
