INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2840888, 395163, 31403, '<td valign="top">blacker blacks would add contrast here and strengthen your image - seems like the left is lower than the right - might be an optical illusion</td>', 'blacker blacks would add contrast here and strengthen your image - seems like the left is lower than the right - might be an optical illusion', '2006-09-16 16:36:37.000000', NULL, 1),
(2840889, 394234, 41800, '<td valign="top">top pencils not quite as sharp as the lower ones, colorful, good lighting,</td>', 'top pencils not quite as sharp as the lower ones, colorful, good lighting,', '2006-09-16 16:37:13.000000', NULL, 1),
(2840891, 395324, 31403, '<td valign="top">I really like the muted tones here - almost like a painting - more "art" like.  This is nice work.  7</td>', 'I really like the muted tones here - almost like a painting - more "art" like.  This is nice work.  7', '2006-09-16 16:38:46.000000', NULL, 1),
(2840893, 395260, 31403, '<td valign="top">oh this is excellent - unfortunately as soon as I say that in a comment that image will finish 184 or lower - sorry!<br/> <br/>The tones and the symmetry here are stunning - I could easily see this hanging in a gallery, AND selling!  Great work.</td>', 'oh this is excellent - unfortunately as soon as I say that in a comment that image will finish 184 or lower - sorry! The tones and the symmetry here are stunning - I could easily see this hanging in a gallery, AND selling!  Great work.', '2006-09-16 16:41:00.000000', NULL, 1),
(2840897, 392553, 31403, '<td valign="top">really cool composition ruined for me by the aggressive saturation.  The magentas have blown out in your yellows - if you would have selected them and desat them - maybe better?  <br/> <br/>The abstract nature of this would have been accented with a 180 degree flip too.<br/> <br/>just thoughts - love the shot and the way you met the challenge - 7 in spite of the saturation and noise!  :-)</td>', 'really cool composition ruined for me by the aggressive saturation.  The magentas have blown out in your yellows - if you would have selected them and desat them - maybe better?   The abstract nature of this would have been accented with a 180 degree flip too. just thoughts - love the shot and the way you met the challenge - 7 in spite of the saturation and noise!  :-)', '2006-09-16 16:43:09.000000', NULL, 1),
(2840963, 394744, 55738, '<td valign="top">This is well composed and well executed, I just don''t find it very compelling.  Maybe a shallower depth of field and deeper contrast would make the colors stand out and make the shot more interesting.</td>', 'This is well composed and well executed, I just don''t find it very compelling.  Maybe a shallower depth of field and deeper contrast would make the colors stand out and make the shot more interesting.', '2006-09-16 17:36:43.000000', NULL, 1),
