(2840969, 395402, 55738, '<td valign="top">This just doesn''t feel as if it''s in focus.  Sorry.</td>', 'This just doesn''t feel as if it''s in focus.  Sorry.', '2006-09-16 17:39:07.000000', NULL, 1),
