(2844765, 395328, 64928, '<td valign="top">I like the way the light catches in the web and on the fern.</td>', 'I like the way the light catches in the web and on the fern.', '2006-09-18 09:52:55.000000', NULL, 1),
(2844770, 395348, 64928, '<td valign="top">This photo is a classice reminder of my younger days in West Texas. The colors are beautiful, and the windmill makes a beautiful sillhouette.</td>', 'This photo is a classice reminder of my younger days in West Texas. The colors are beautiful, and the windmill makes a beautiful sillhouette.', '2006-09-18 09:55:13.000000', NULL, 1),
