(2848640, 392131, 42100, '<td valign="top">Nice job of using everyday items for an interesting composition and great b&amp;w photo.  Now go take those office supplies back to where they belong!</td>', 'Nice job of using everyday items for an interesting composition and great b&w photo.  Now go take those office supplies back to where they belong!', '2006-09-19 21:01:52.000000', NULL, 1),
(2848644, 395190, 42100, '<td valign="top">Very interesting high-key photograph, a good looking graphic style photo.  Well done!</td>', 'Very interesting high-key photograph, a good looking graphic style photo.  Well done!', '2006-09-19 21:03:03.000000', NULL, 1),
(2848649, 392876, 42100, '<td valign="top">Very serene and graphic style photograph.  The old wood of the boat has lots of character.  Well done!</td>', 'Very serene and graphic style photograph.  The old wood of the boat has lots of character.  Well done!', '2006-09-19 21:04:54.000000', NULL, 1),
(2848655, 395028, 42100, '<td valign="top">Whew, very bright...great color and cool composition.  Creative idea and well executed.</td>', 'Whew, very bright...great color and cool composition.  Creative idea and well executed.', '2006-09-19 21:07:32.000000', NULL, 1),
(2849117, 392902, 65858, '<td valign="top">This photo looks interesting, but it seems that there is too much jpeg compression.  You can see the artifacts around the moon the most.  Whatever program you use to resize it, you should make sure the quality of the output is set high.</td>', 'This photo looks interesting, but it seems that there is too much jpeg compression.  You can see the artifacts around the moon the most.  Whatever program you use to resize it, you should make sure the quality of the output is set high.', '2006-09-19 23:45:15.000000', NULL, 1),
(2849123, 393613, 65858, '<td valign="top">Fascinating shot!  I like the composition and the subject.  I might like to see it untilted.</td>', 'Fascinating shot!  I like the composition and the subject.  I might like to see it untilted.', '2006-09-19 23:47:12.000000', NULL, 1),
(2849128, 392304, 65858, '<td valign="top">Great subject.  Was there a way you could frame it to reduce the external distraction a bit?  Very nice.</td>', 'Great subject.  Was there a way you could frame it to reduce the external distraction a bit?  Very nice.', '2006-09-19 23:48:48.000000', NULL, 1),
(2849129, 394865, 65858, '<td valign="top">Simple and elegant.</td>', 'Simple and elegant.', '2006-09-19 23:48:58.000000', NULL, 1),
(2849132, 395260, 65858, '<td valign="top">Excellent symmetry.  I actually like the grain in this photo.</td>', 'Excellent symmetry.  I actually like the grain in this photo.', '2006-09-19 23:49:59.000000', NULL, 1),
