(2849708, 392995, 30861, '<td valign="top">Whoo! Congratulations, June! dSLR pays off, doing what it does best!</td>', 'Whoo! Congratulations, June! dSLR pays off, doing what it does best!', '2006-09-20 02:40:53.000000', NULL, 0),
